  1023  static GVariantSerialised
  1024  gvs_tuple_get_child (GVariantSerialised value,
  1025                       gsize              index_)
  1026  {
  1027    const GVariantMemberInfo *member_info;
  1028    GVariantSerialised child = { 0, };
  1029    gsize offset_size;
  1030    gsize start, end, last_end;
  1031
  1032    member_info = g_variant_type_info_member_info (value.type_info, index_);
  1033    child.type_info = g_variant_type_info_ref (member_info->type_info);
  1034    child.depth = value.depth + 1;
  1035    offset_size = gvs_get_offset_size (value.size);
  1036
  1037    /* Ensure the size is set for fixed-sized children, or
  1038     * g_variant_serialised_check() will fail, even if we return
  1039     * (child.data == NULL) to indicate an error. */
  1040    if (member_info->ending_type == G_VARIANT_MEMBER_ENDING_FIXED)
  1041      g_variant_type_info_query (child.type_info, NULL, &child.size);
  1042
  1043    /* tuples are the only (potentially) fixed-sized containers, so the
  1044     * only ones that have to deal with the possibility of having %NULL
  1045     * data with a non-zero %size if errors occurred elsewhere.
  1046     */
  1047    if G_UNLIKELY (value.data == NULL && value.size != 0)
  1048      {
  1049        /* this can only happen in fixed-sized tuples,
  1050         * so the child must also be fixed sized.
  1051         */
  1052        g_assert (child.size != 0);
  1053        child.data = NULL;
  1054
  1055        return child;
  1056      }
  1057
  1058    /* If the requested @index_ is beyond the set of indices whose framing offsets
  1059     * have been checked, check the remaining offsets to see whether they’re
  1060     * normal (in order, no overlapping tuple elements).
  1061     *
  1062     * Unlike the checks in gvs_variable_sized_array_get_child(), we have to check
  1063     * all the tuple *elements* here, not just all the framing offsets, since
  1064     * tuples contain a mix of elements which use framing offsets and ones which
  1065     * don’t. None of them are allowed to overlap. */
  1066    if (index_ > value.checked_offsets_up_to &&
  1067        value.ordered_offsets_up_to == value.checked_offsets_up_to)
  1068      {
  1069        gsize i, prev_i_end = 0;
  1070
  1071        if (value.checked_offsets_up_to > 0)
  1072          gvs_tuple_get_member_bounds (value, value.checked_offsets_up_to - 1, offset_size, NULL, &prev_i_end);
  1073
  1074        for (i = value.checked_offsets_up_to; i <= index_; i++)
  1075          {
  1076            gsize i_start, i_end;
  1077
  1078            gvs_tuple_get_member_bounds (value, i, offset_size, &i_start, &i_end);
  1079
  1080            if (i_start > i_end || i_start < prev_i_end || i_end > value.size)
  1081              break;
  1082
  1083            prev_i_end = i_end;
  1084          }
  1085
  1086        value.ordered_offsets_up_to = i - 1;
  1087        value.checked_offsets_up_to = index_;
  1088      }
  1089
  1090    if (index_ > value.ordered_offsets_up_to)
  1091      {
  1092        /* Offsets are invalid somewhere, so return an empty child. */
  1093        return child;
  1094      }
  1095
  1096    if (member_info->ending_type == G_VARIANT_MEMBER_ENDING_OFFSET)
  1097      {
  1098        if (offset_size * (member_info->i + 2) > value.size)
  1099          return child;
  1100      }
  1101    else
  1102      {
  1103        if (offset_size * (member_info->i + 1) > value.size)
  1104          return child;
  1105      }
  1106
  1107    /* The child should not extend into the offset table. */
  1108    gvs_tuple_get_member_bounds (value, index_, offset_size, &start, &end);
  1109    gvs_tuple_get_member_bounds (value, g_variant_type_info_n_members (value.type_info) - 1, offset_size, NULL, &last_end);
  1110
  1111    if (start < end && end <= value.size && end <= last_end)
  1112      {
  1113        child.data = value.data + start;
  1114        child.size = end - start;
  1115      }
  1116
  1117    return child;
  1118  }
