  1150
  1151        if (fixed_size)
  1152          offset += fixed_size;
  1153        else
  1154          {
  1155            GVariantSerialised child = { 0, };
  1156
  1157            gvs_filler (&child, children[i]);
  1158            offset += child.size;
  1159          }
  1160      }
  1161
  1162    return gvs_calculate_total_size (offset, member_info->i + 1);
  1163  }
